#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <stdbool.h>

typedef struct {
    const char *s;
    int pos;
    int len;
} Parser;

static void skip_ws(Parser *p) {
    while (p->pos < p->len && isspace((unsigned char)p->s[p->pos])) {
        p->pos++;
    }
}

static void expect_char(Parser *p, char c) {
    skip_ws(p);
    if (p->pos >= p->len || p->s[p->pos] != c) exit(2);
    p->pos++;
}

static int parse_int(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len || !isdigit((unsigned char)p->s[p->pos])) exit(2);

    int value = 0;
    while (p->pos < p->len && isdigit((unsigned char)p->s[p->pos])) {
        value = value * 10 + (p->s[p->pos] - '0');
        p->pos++;
    }
    return value;
}

static int *parse_row(Parser *p, int *size) {
    expect_char(p, '[');
    skip_ws(p);

    if (p->pos < p->len && p->s[p->pos] == ']') {
        p->pos++;
        *size = 0;
        return NULL;
    }

    int capacity = 4;
    int count = 0;
    int *row = (int *)malloc(capacity * sizeof(int));
    if (!row) exit(3);

    while (1) {
        if (count == capacity) {
            capacity *= 2;
            int *tmp = (int *)realloc(row, capacity * sizeof(int));
            if (!tmp) {
                free(row);
                exit(3);
            }
            row = tmp;
        }

        row[count++] = parse_int(p);
        skip_ws(p);

        if (p->pos < p->len && p->s[p->pos] == ',') {
            p->pos++;
        } else {
            break;
        }
    }

    expect_char(p, ']');
    *size = count;
    return row;
}

static int **parse_graph(Parser *p, int *n, int **col_sizes) {
    expect_char(p, '[');
    skip_ws(p);

    int capacity = 4;
    int count = 0;
    int **graph = (int **)malloc(capacity * sizeof(int *));
    int *cols = (int *)malloc(capacity * sizeof(int));
    if (!graph || !cols) exit(3);

    if (p->pos < p->len && p->s[p->pos] == ']') {
        p->pos++;
        *n = 0;
        *col_sizes = cols;
        return graph;
    }

    while (1) {
        if (count == capacity) {
            capacity *= 2;
            int **new_graph = (int **)realloc(graph, capacity * sizeof(int *));
            int *new_cols = (int *)realloc(cols, capacity * sizeof(int));
            if (!new_graph || !new_cols) exit(3);
            graph = new_graph;
            cols = new_cols;
        }

        graph[count] = parse_row(p, &cols[count]);
        count++;

        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') {
            p->pos++;
        } else {
            break;
        }
    }

    expect_char(p, ']');
    *n = count;
    *col_sizes = cols;
    return graph;
}

static bool isBipartite(int **graph, int graphSize, int *graphColSize) {
    int *color = (int *)malloc((size_t)graphSize * sizeof(int));
    int *queue = (int *)malloc((size_t)graphSize * sizeof(int));
    if (!color || !queue) exit(3);

    for (int i = 0; i < graphSize; i++) color[i] = -1;

    for (int start = 0; start < graphSize; start++) {
        if (color[start] != -1) continue;

        int head = 0, tail = 0;
        color[start] = 0;
        queue[tail++] = start;

        while (head < tail) {
            int u = queue[head++];

            for (int i = 0; i < graphColSize[u]; i++) {
                int v = graph[u][i];

                if (color[v] == -1) {
                    color[v] = color[u] ^ 1;
                    queue[tail++] = v;
                } else if (color[v] == color[u]) {
                    free(color);
                    free(queue);
                    return false;
                }
            }
        }
    }

    free(color);
    free(queue);
    return true;
}

int main(void) {
    char *input = (char *)malloc(2000000);
    if (!input) return 3;

    size_t len = 0;
    int ch;
    while ((ch = getchar()) != EOF) {
        if (len + 1 >= 2000000) {
            free(input);
            return 3;
        }
        input[len++] = (char)ch;
    }
    input[len] = '\0';

    Parser parser = { input, 0, (int)len };

    expect_char(&parser, '[');
    int n = 0;
    int *cols = NULL;
    int **graph = parse_graph(&parser, &n, &cols);
    expect_char(&parser, ']');

    bool result = isBipartite(graph, n, cols);
    printf("%s\n", result ? "true" : "false");

    for (int i = 0; i < n; i++) free(graph[i]);
    free(graph);
    free(cols);
    free(input);
    return 0;
}

