import java.io.*;
import java.util.*;

class Solution {
    public boolean isBipartite(int[][] graph) {
        int n = graph.length;
        int[] color = new int[n];
        Arrays.fill(color, -1);

        ArrayDeque<Integer> queue = new ArrayDeque<>();

        for (int start = 0; start < n; start++) {
            if (color[start] != -1) continue;

            color[start] = 0;
            queue.add(start);

            while (!queue.isEmpty()) {
                int u = queue.remove();

                for (int v : graph[u]) {
                    if (color[v] == -1) {
                        color[v] = color[u] ^ 1;
                        queue.add(v);
                    } else if (color[v] == color[u]) {
                        return false;
                    }
                }
            }
        }

        return true;
    }
}

public class Main {
    static class Parser {
        private final String s;
        private int p = 0;

        Parser(String s) {
            this.s = s;
        }

        void skip() {
            while (p < s.length() && Character.isWhitespace(s.charAt(p))) p++;
        }

        void expect(char c) {
            skip();
            if (p >= s.length() || s.charAt(p) != c) {
                throw new IllegalArgumentException("Invalid input");
            }
            p++;
        }

        int parseInt() {
            skip();
            int start = p;
            while (p < s.length() && Character.isDigit(s.charAt(p))) p++;
            if (start == p) throw new IllegalArgumentException("Expected integer");
            return Integer.parseInt(s.substring(start, p));
        }

        int[] parseRow() {
            expect('[');
            skip();

            if (p < s.length() && s.charAt(p) == ']') {
                p++;
                return new int[0];
            }

            ArrayList<Integer> values = new ArrayList<>();
            while (true) {
                values.add(parseInt());
                skip();
                if (p < s.length() && s.charAt(p) == ',') {
                    p++;
                } else {
                    break;
                }
            }

            expect(']');
            int[] row = new int[values.size()];
            for (int i = 0; i < row.length; i++) row[i] = values.get(i);
            return row;
        }

        int[][] parseGraph() {
            expect('[');
            skip();

            ArrayList<int[]> rows = new ArrayList<>();
            if (p < s.length() && s.charAt(p) == ']') {
                p++;
                return new int[0][];
            }

            while (true) {
                rows.add(parseRow());
                skip();
                if (p < s.length() && s.charAt(p) == ',') {
                    p++;
                } else {
                    break;
                }
            }

            expect(']');
            return rows.toArray(new int[0][]);
        }

        int[][] parseArguments() {
            expect('[');
            int[][] graph = parseGraph();
            expect(']');
            return graph;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder input = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) input.append(line);

        int[][] graph = new Parser(input.toString()).parseArguments();
        boolean result = new Solution().isBipartite(graph);
        System.out.println(result);
    }
}

